#include <Wire.h>
#include <LiquidCrystal_I2C.h>
#include <Keyboard.h>

LiquidCrystal_I2C lcd(0x27, 16, 2);

const int buttonPins[] = {2, 3, 4, 5};
const int numButtons = 4;

const char* macros[] = {"Macro 1", "Macro 2", "Macro 3", "Macro 4"};

int lastButtonStates[] = {HIGH, HIGH, HIGH, HIGH};

void setup() {
  lcd.init();
  lcd.backlight();
  lcd.setCursor(0, 0);
  lcd.print("Macro Pad Ready");

  for (int i = 0; i < numButtons; i++) {
    pinMode(buttonPins[i], INPUT_PULLUP);
  }

  Keyboard.begin();
}

void loop() {
  for (int i = 0; i < numButtons; i++) {
    int buttonState = digitalRead(buttonPins[i]);

    if (buttonState == LOW && lastButtonStates[i] == HIGH) {
      delay(50); 
      if (digitalRead(buttonPins[i]) == LOW) {
        lcd.clear();
        lcd.setCursor(0, 0);
        lcd.print("Executing:");
        lcd.setCursor(0, 1);
        lcd.print(macros[i]);

        executeMacro(i);

        delay(1000);
        lcd.clear();
        lcd.setCursor(0, 0);
        lcd.print("Macro Pad Ready");
      }
    }
    lastButtonStates[i] = buttonState;
  }
}

void executeMacro(int index) {
  switch (index) {
    case 0:
      Keyboard.print("Hello from Macro 1!");
      break;
    case 1:
      Keyboard.println("Macro 2 executed");
      break;
    case 2:
      Keyboard.press(KEY_LEFT_CTRL);
      Keyboard.press('c');
      delay(50);
      Keyboard.releaseAll();
      break;
    case 3:
      Keyboard.press(KEY_LEFT_GUI);
      Keyboard.press('v');
      delay(50);
      Keyboard.releaseAll();
      break;
  }
}
